from pathlib import Path
import base64
import gzip

path = Path('_site/index.html')
text = path.read_text(encoding='utf-8')

builder_gz_b64 = ''''''

builder_js = gzip.decompress(base64.b64decode(builder_gz_b64)).decode('utf-8')
Path('_site/builder_v1.js').write_text(builder_js, encoding='utf-8')

marker = '<script src="./builder_v1.js"></script>'

# Remove apenas o gerador automático de Humanas/mistão. A professora ainda
# pode combinar disciplinas conscientemente no construtor manual.
text = text.replace(
    "let arr=['sociologia','filosofia','historia','geografia','humanas'];",
    "let arr=['sociologia','filosofia','historia','geografia'];"
)

# Dá um id estável ao cartão de dados para a interface v1.0 simplificá-lo.
text = text.replace(
    '<div class="card"><div class="grid">',
    '<div class="card" id="evaluationDataCard"><div class="grid">',
    1
)

if marker not in text:
    closing = '</script></body></html>'
    if closing not in text:
        raise SystemExit('v1.0: fechamento principal não encontrado')
    text = text.replace(closing, f'</script>{marker}</body></html>', 1)

text = text.replace('Adelita v0.9.1</title>', 'Adelita v1.0</title>')
text = text.replace('para a Profa. Adelita · v0.9.1</small>', 'para a Profa. Adelita · v1.0</small>')

if marker not in text:
    raise SystemExit('v1.0: builder_v1.js não foi ligado ao app')
if "['sociologia','filosofia','historia','geografia','humanas']" in text:
    raise SystemExit('v1.0: opção automática Humanas ainda está na navegação')
if '// ASSESSMENT-BUILDER-v1.0' not in builder_js:
    raise SystemExit('v1.0: bundle do construtor inválido')

path.write_text(text, encoding='utf-8')
print('Hotfix v1.0 aplicado: construtor manual, rascunho persistente e DOCX principal')
